import{_ as r,l as o,o as e,c as p,v as t,p as n,x as i,d,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const z=JSON.parse('{"title":"条件要素需求","description":"","frontmatter":{"title":"条件要素需求","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/conditional-factor-demand.md","filePath":"econ/conditional-factor-demand.md","lastUpdated":1789023840000}'),h={name:"econ/conditional-factor-demand.md"};function q(w,a,_,m,A,E){const l=o("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="条件要素需求" tabindex="-1">条件要素需求 <a class="header-anchor" href="#条件要素需求" aria-label="Permalink to &quot;条件要素需求&quot;">​</a></h1><div class="epigraph"><p>锁住产量时要素如何随工资替换，与放开产量后要素如何随工资、产品价格一起动，是两条曲线——前者没有产出效应。</p><footer>—— 据 Varian, Microeconomic Analysis；对照 Shephard 与 Hotelling 引理</footer></div><p><a href="/econ/shephard-hotelling">上一课</a>用包络读出 \\(z(w,q)=\\nabla_w c\\) 与无条件的 \\(z(p,w)=-\\nabla_w\\pi\\)。本课不重证两条引理。缺口是把二者的差别写成可调用的语言：后课劳动市场、税收归宿若把「要素需求」画成一条，会漏掉 \\(q\\) 随 \\(p\\) 动的那一层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>条件要素需求 \\(z(w,q)\\) 回答：产出锁在 \\(q\\) 时，要素价格变，厂商沿等产量如何换投入。它是成本最小化的解，齐次零次于 \\(w\\)，对 \\(q\\) 在一次齐次技术上线性。无条件要素需求 \\(z(p,w)\\) 回答：产品价格也给定、产量已经按利润最大调过之后，要素用多少。缺口是恒等式</p> \\[z_j(p,w)=z_j\\bigl(w,q(p,w)\\bigr), \\]<p>从而对 \\(w_k\\) 的导数多出一项产出效应：\\(\\partial z_j/\\partial q\\cdot\\partial q/\\partial w_k\\)。Shephard 只看见第一项（替代）；Hotelling 看见两项之和。把条件劳动需求直接贴到劳动市场上，等于假定产品市场的 \\(q\\) 冻住——短长期课有时故意这样做，但必须声明。</p><h3 id="替代矩阵不是要素市场的斜率" tabindex="-1">替代矩阵不是要素市场的斜率 <a class="header-anchor" href="#替代矩阵不是要素市场的斜率" aria-label="Permalink to &quot;替代矩阵不是要素市场的斜率&quot;">​</a></h3><p>\\(c\\) 对 \\(w\\) 凹，故 \\(D_w z(w,q)\\) 半负定、对称（可微时）。这是沿等产量的替代，类似希克斯需求。无条件需求对 \\(w\\) 的斜率还含 \\(q\\) 的调整，符号仍通常为负（要素作为利润问题里的「劣」价格），但弹性更大。不要把 Allen–Uzawa 替代弹性写成劳动需求的市场弹性。</p><p><span class="marginnote">消费者斯勒茨基：马歇尔 = 希克斯 + 财富项。厂商这里：无条件 = 条件 + 产出项。财富与产出不是同一通道，只是对偶平行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(w,q\\)，用 Shephard 或等产量切点算 \\(z(w,q)\\)。给定 \\(p,w\\)，先由 \\(p=\\mathrm{MC}(q)\\) 解出 \\(q(p,w)\\)（下一课把这条供给写全），再代入条件需求。比较两条曲线：条件曲线沿等产量，无条件曲线沿扩张路径加上等产量滑动。</p><p>位似或一次齐次时，扩张路径是射线，\\(z(w,q)=q\\,a(w)\\)，产出效应与规模成比例。里昂惕夫没有替代，条件需求对 \\(w\\) 无弹性，无条件弹性全部来自 \\(q\\)。本课只标明分解，不估数字。</p>',13)),(e(),n(c,null,{default:i(()=>[s(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22Shephard%EF%BC%9Az(w%2Cq)%22%5D%20--%3E%20COND%5B%22%E7%AD%89%E4%BA%A7%E9%87%8F%E4%B8%8A%E7%9A%84%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20HOT%5B%22Hotelling%EF%BC%9Az(p%2Cw)%22%5D%20--%3E%20UNC%5B%22%E6%9B%BF%E4%BB%A3%20%2B%20%E4%BA%A7%E5%87%BA%E6%95%88%E5%BA%94%22%5D%0A%20%20COND%20--%3E%20ID%5B%22z(p%2Cw)%3Dz(w%2C%20q(p%2Cw))%22%5D%0A%20%20UNC%20--%3E%20ID%0A%20%20ID%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%94%A8%20%CF%80%20%E6%8A%8A%20q%20%E5%86%85%E7%94%9F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课 \\(p\\) 仍是参数。要素市场出清、买方垄断不在这里。也不把 \\(z\\) 写成限价簿上愿意成交的库存。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>产出效应的机制：\\(w_k\\) 上升 → 边际成本上升 → 最优 \\(q\\) 下降 → 所有正常要素少用。即使某种要素与 \\(k\\) 在等产量上是互补还是替代，这一层通常同向减少投入。条件需求把这层关掉，于是只剩「贵的要素被便宜的要素替换」，可能出现交叉价格为正（替代）。无条件交叉价格还要叠加规模收缩，净效应不定。</p><p>与成本课的接口：上一课已经警告不要把 \\(z(w,q)\\) 当成要素市场反函数。本课给出正确的叠法。与利润课的接口：Hotelling 的 \\(-\\partial\\pi/\\partial w\\) 自动含两层；若实证只观察到 \\(q\\) 与 \\(z\\)，要用条件还是无条件，取决于数据里 \\(q\\) 是否被控制。</p><p><span class="marginnote">短长期：资本沉没时，条件需求里一部分 \\(z\\) 不再对当期 \\(w\\) 反应，那是下一课之后的对象。本课默认全部投入可按 \\(w\\) 重选。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>联合生产、\\(q\\) 为向量时，产出效应是一条链 \\(\\partial z/\\partial q\\cdot\\partial q/\\partial w\\)。配额使 \\(q\\) 外生，无条件退化成条件——管制产业常用这一刀。IRS 下 \\(q(p,w)\\) 可以没有有限解，无条件需求整段不好定义；条件需求在给定 \\(q\\) 上仍可写。</p><p>也不处理要素质量、效率单位。本课 \\(z\\) 是物理投入。量化栏的成交量不是条件需求：这里没有报价，只有计划投入。</p><p>后课默认：写要素需求必须声明锁不锁 \\(q\\)；锁住的是 \\(z(w,q)\\)，放开的是 \\(z(p,w)\\)，二者差产出效应。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(z(w,q)\\) 沿等产量；\\(z(p,w)\\) 等于把最优 \\(q\\) 代回条件需求。</li><li>无条件斜率 = 替代（Shephard）+ 产出效应；市场弹性常用后者。</li><li>一次齐次时条件需求对 \\(q\\) 线性，产出效应成比例。</li><li>下一课把 \\(q\\) 放开，用利润最大写出供给。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Shephard, 1953；Hotelling, <em>JPE</em>, 1932。</li></ul>',11))])}const f=r(h,[["render",q]]);export{z as __pageData,f as default};
